  "test": "import request from 'supertest';
import { beforeEach, describe, expect, it } from 'vitest';
import { createApp } from '../src/app';
import { createDb, type DB } from '../src/db';

let db: DB;
let app: ReturnType<typeof createApp>;

beforeEach(() => {
  db = createDb();
  app = createApp(db);
});

describe('regresión sql-interpolation en categoría', () => {
  it('previene inyección sql y maneja correctamente caracteres especiales en category', async () => {
    const res = await request(app).get(
      `/stores/online/products?category=${encodeURIComponent("moda' OR '1'='1")}`,
    );
    expect(res.status).toBe(200);
    expect(res.body.items).toEqual([]);
  });
});
